1	/**
2	 * BG-3: the webhook listener. Off unless the runner is started with a webhook port AND an approved webhook trigger
3	 * exists; it binds loopback unless the operator asks for more and authentication is configured.
4	 *
5	 * A delivery is `POST /hook/<workspace key>/<trigger id>` with three headers:
6	 *   X-Nexus-Timestamp  seconds since the epoch; more than 5 minutes from now (or before the listener started) is refused
7	 *   X-Nexus-Delivery   a unique id of 8..64 characters of [A-Za-z0-9_.-]; one id is accepted once
8	 *   X-Nexus-Signature  sha256=<hex>, the HMAC-SHA256 of `<timestamp>.<delivery>.<raw body>` under the trigger's secret
9	 * The order of the checks is the design (docs/TRIGGERS.md):
10	 *   1. before any body is read: the Host header is a loopback name (DNS rebinding), a route and an approved trigger
11	 *      exist, an Origin header is only accepted if the spec lists it, the declared size is within the cap;
12	 *   2. the body is read raw up to the cap, under header and request timeouts, then the signature is checked in
13	 *      constant time (against a dummy key when there is no such trigger, so the work does not tell);
14	 *   3. only then the delivery id is recorded (a replay is refused here) and `onDelivery` runs: the rate limiter and
15	 *      everything after it. A caller that cannot sign never reaches the limiter, so it cannot spend a trigger's budget.
16	 * Everything refused before step 3 gets the same status and body, so a caller cannot tell which check failed.
17	 * Nothing in the body is parsed here: the firer passes a capped, escaped preview to the job as data.
18	 */
19	import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
20	import * as http from "node:http";
21	import type { AddressInfo } from "node:net";
22	
23	export const MAX_BODY_BYTES = 64 * 1024;
24	export const MAX_HEADER_BYTES = 8 * 1024;
25	export const MAX_CONNECTIONS = 32;
26	export const SKEW_SECONDS = 300;
27	export const REPLAY_MAX = 4096;
28	export const REPLAY_TTL_MS = 2 * SKEW_SECONDS * 1000;
29	const REFUSED = JSON.stringify({ error: "refused" });
30	const ROUTE = /^\/hook\/([0-9a-f]{12})\/([a-z0-9][a-z0-9-]{0,62})$/;
31	const DELIVERY = /^[A-Za-z0-9][A-Za-z0-9_.-]{7,63}$/;
32	const SIGNATURE = /^sha256=([0-9a-f]{64})$/;
33	
34	export const isLoopbackAddress = (host: string): boolean => /^127(?:\.\d{1,3}){3}$/.test(host) || host === "::1" || host === "localhost";
35	
36	/** What the firer knows about one approved webhook trigger. */
37	export interface WebhookTarget {
38	  secret: Buffer;
39	  /** Origins the spec lists; an `Origin` header outside them is refused. */
40	  allowedOrigins: readonly string[];
41	}
42	
43	export interface WebhookDelivery {
44	  workspaceKey: string;
45	  id: string;
46	  deliveryId: string;
47	  /** The raw body, at most `MAX_BODY_BYTES`. */
48	  body: Buffer;
49	}
50	
51	/** What an authenticated caller is told. `reason` is a short code from a fixed set. */
52	export type WebhookOutcome = { accepted: true } | { accepted: false; reason: "rate-limited" | "quarantined" | "busy" | "refused" };
53	
54	export interface WebhookOptions {
55	  host: string;
56	  port: number;
57	  allowNonLoopback?: boolean;
58	  /** Whether any approved webhook trigger has a secret: a non-loopback bind is refused without one. */
59	  hasAuthentication: () => boolean;
60	  lookup: (workspaceKey: string, id: string) => WebhookTarget | undefined;
61	  onDelivery: (delivery: WebhookDelivery, nowMs: number) => WebhookOutcome;
62	  maxBodyBytes?: number;
63	  requestTimeoutMs?: number;
64	  maxConnections?: number;
65	  now?: () => number;
66	}
67	
68	/** Delivery ids seen in the last `ttlMs`, bounded. Full means refuse: a new id is never admitted by forgetting an old one. */
69	export class ReplayCache {
70	  private readonly seen = new Map<string, number>();
71	  constructor(private readonly max: number = REPLAY_MAX, private readonly ttlMs: number = REPLAY_TTL_MS) {}
72	
73	  admit(key: string, nowMs: number): boolean {
74	    for (const [oldKey, expires] of this.seen) {
75	      if (expires > nowMs) break;
76	      this.seen.delete(oldKey);
77	    }
78	    if (this.seen.has(key) || this.seen.size >= this.max) return false;
79	    this.seen.set(key, nowMs + this.ttlMs);
80	    return true;
81	  }
82	
83	  size(): number {
84	    return this.seen.size;
85	  }
86	}
87	
88	export class WebhookListener {
89	  private server: http.Server | undefined;
90	  private readonly replay = new ReplayCache();
91	  private readonly dummy = randomBytes(32);
92	  private startedAtSeconds = 0;
93	  private hostNames = new Set<string>();
94	
95	  constructor(private readonly options: WebhookOptions) {}
96	
97	  private now(): number {
98	    return this.options.now?.() ?? Date.now();
99	  }
100	
101	  /** Opens the listener. Rejects (and opens nothing) when the bind is not allowed. */
102	  async start(): Promise<{ host: string; port: number }> {
103	    const { port } = this.options;
104	    const host = this.options.host === "localhost" ? "127.0.0.1" : this.options.host;
105	    if (!isLoopbackAddress(host)) {
106	      if (this.options.allowNonLoopback !== true) throw new Error(`the webhook listener binds loopback only; ${host} needs the explicit non-loopback flag`);
107	      if (!this.options.hasAuthentication()) throw new Error(`the webhook listener refuses to bind ${host}: no approved webhook trigger has a secret configured`);
108	    }
109	    const requestTimeout = this.options.requestTimeoutMs ?? 10_000;
110	    const server = http.createServer({
111	      maxHeaderSize: MAX_HEADER_BYTES,
112	      requestTimeout,
113	      headersTimeout: Math.min(requestTimeout, 5_000),
114	      keepAliveTimeout: 1_000,
115	      connectionsCheckingInterval: Math.max(50, Math.min(1_000, Math.floor(requestTimeout / 2))),
116	    }, (req, res) => this.handle(req, res));
117	    server.maxConnections = this.options.maxConnections ?? MAX_CONNECTIONS;
118	    server.maxRequestsPerSocket = 1;
119	    server.on("clientError", (_error, socket) => {
120	      if (socket.writable) socket.end("HTTP/1.1 400 Bad Request\r\nconnection: close\r\ncontent-length: 0\r\n\r\n");
121	      else socket.destroy();
122	    });
123	    await new Promise<void>((resolve, reject) => {
124	      server.once("error", reject);
125	      server.listen({ host, port, exclusive: true }, () => {
126	        server.off("error", reject);
127	        resolve();
128	      });
129	    });
130	    this.server = server;
131	    this.startedAtSeconds = Math.floor(this.now() / 1000);
132	    const address = server.address() as AddressInfo;
133	    this.hostNames = new Set(["127.0.0.1", "localhost", "[::1]", ...(isLoopbackAddress(host) ? [] : [host.toLowerCase()])]);
134	    this.boundPort = address.port;
135	    return { host: address.address, port: address.port };
136	  }
137	
138	  private boundPort = 0;
139	
140	  get listening(): boolean {
141	    return this.server?.listening === true;
142	  }
143	
144	  async close(): Promise<void> {
145	    const server = this.server;
146	    this.server = undefined;
147	    if (!server) return;
148	    await new Promise<void>((resolve) => {
149	      server.close(() => resolve());
150	      server.closeAllConnections();
151	    });
152	  }
153	
154	  private hostAllowed(header: unknown): boolean {
155	    if (typeof header !== "string" || header.length > 255) return false;
156	    const match = /^(\[[0-9a-f:]+\]|[A-Za-z0-9.-]+)(?::(\d{1,5}))?$/i.exec(header);
157	    if (!match) return false;
158	    if (match[2] !== undefined && Number(match[2]) !== this.boundPort) return false;
159	    return this.hostNames.has(match[1]!.toLowerCase());
160	  }
161	
162	  private send(res: http.ServerResponse, status: number, body: string): void {
163	    if (res.headersSent) return;
164	    res.writeHead(status, { "content-type": "application/json", "content-length": Buffer.byteLength(body), connection: "close", "cache-control": "no-store" });
165	    res.end(body);
166	    res.once("finish", () => res.socket?.destroy());
167	  }
168	
169	  private handle(req: http.IncomingMessage, res: http.ServerResponse): void {
170	    const refuse = () => this.send(res, 401, REFUSED);
171	    const route = ROUTE.exec(req.url ?? "");
172	    if (req.method !== "POST" || !route || !this.hostAllowed(req.headers.host)) return refuse();
173	    const target = this.options.lookup(route[1]!, route[2]!);
174	    const origin = req.headers.origin;
175	    if (origin !== undefined && !(typeof origin === "string" && target?.allowedOrigins.some((allowed) => allowed.toLowerCase() === origin.toLowerCase()))) return refuse();
176	    const max = this.options.maxBodyBytes ?? MAX_BODY_BYTES;
177	    const declared = req.headers["content-length"];
178	    if (declared !== undefined) {
179	      if (typeof declared !== "string" || !/^\d{1,9}$/.test(declared)) return refuse();
180	      if (Number(declared) > max) return this.send(res, 413, JSON.stringify({ error: "too large" }));
181	    }
182	    const chunks: Buffer[] = [];
183	    let size = 0;
184	    let over = false;
185	    req.on("data", (chunk: Buffer) => {
186	      if (over) return;
187	      size += chunk.length;
188	      if (size > max) {
189	        over = true;
190	        chunks.length = 0;
191	        this.send(res, 413, JSON.stringify({ error: "too large" }));
192	        return;
193	      }
194	      chunks.push(chunk);
195	    });
196	    req.on("error", () => res.socket?.destroy());
197	    req.on("end", () => {
198	      if (over) return;
199	      try {
200	        this.authenticated(req, res, route[1]!, route[2]!, target, Buffer.concat(chunks), refuse);
201	      } catch {
202	        this.send(res, 500, JSON.stringify({ error: "failed" }));
203	      }
204	    });
205	  }
206	
207	  private authenticated(req: http.IncomingMessage, res: http.ServerResponse, workspaceKey: string, id: string, target: WebhookTarget | undefined, body: Buffer, refuse: () => void): void {
208	    const header = (name: string): string | undefined => (typeof req.headers[name] === "string" ? (req.headers[name] as string) : undefined);
209	    const timestamp = header("x-nexus-timestamp") ?? "";
210	    const delivery = header("x-nexus-delivery") ?? "";
211	    const signature = SIGNATURE.exec(header("x-nexus-signature") ?? "")?.[1];
212	    const nowMs = this.now();
213	    const seconds = /^\d{9,11}$/.test(timestamp) ? Number(timestamp) : undefined;
214	    const fresh = seconds !== undefined && Math.abs(nowMs / 1000 - seconds) <= SKEW_SECONDS && seconds >= this.startedAtSeconds;
215	    // The work is the same whatever failed: an HMAC is always computed, against a dummy key when there is no trigger.
216	    const mac = createHmac("sha256", target?.secret ?? this.dummy).update(`${timestamp}.${delivery}.`).update(body).digest();
217	    const given = Buffer.from(signature ?? "0".repeat(64), "hex");
218	    const signed = timingSafeEqual(mac, given) && signature !== undefined;
219	    if (!(target !== undefined && signed && fresh && DELIVERY.test(delivery))) return refuse();
220	    // Authenticated. A replay is refused before it can touch the limiter.
221	    if (!this.replay.admit(`${workspaceKey}/${id}/${delivery}`, nowMs)) return refuse();
222	    const outcome = this.options.onDelivery({ workspaceKey, id, deliveryId: delivery, body }, nowMs);
223	    if (outcome.accepted) this.send(res, 202, JSON.stringify({ status: "accepted" }));
224	    else this.send(res, 429, JSON.stringify({ status: "not-started", reason: outcome.reason }));
225	  }
226	}
