1	/**
2	 * BG-3: the trigger firer. It runs inside the detached runner (`nexus runner serve`) beside the schedule engine and
3	 * starts nothing itself: a fire is a job submission through the runner's own acceptance (`job_submission.ts`, the code
4	 * `nexus job start` and schedules use), so it has a fresh worktree, the unattended rules, no auto mode, no
5	 * allow-always and the bounded auto-resumes of every job. An event only decides WHEN, and says what happened.
6	 *
7	 * What is approved is what fires. Every scan and every fire re-reads the trust store and the spec file ONCE, hashes each
8	 * spec's canonical form, compares it with the approval, re-checks that the workspace is still trusted and that its
9	 * real path has not moved, and fires from that same parse. An unapproved, changed, revoked, rate-limited, quarantined
10	 * or untrusted-workspace trigger fires nothing and the reason is recorded where `nexus triggers status` shows it.
11	 *
12	 * Nothing exists until it is needed: with no approved trigger there is no watcher, no listener, no socket and no file.
13	 * Events that do not start a job (flood, rate limit, quarantine, a previous job still running, a repeated id) are
14	 * counted by reason and dropped; they are never queued and never replayed as a burst.
15	 */
16	import { createHash } from "node:crypto";
17	import * as fs from "node:fs";
18	import { isTerminal, listJobs, RunnerStoreError, type JobRecord, type JobSubmission, type RunnerPaths } from "./runner_store.js";
19	import { parseTriggerFile, specSha256, triggerFilePath } from "./trigger_load.js";
20	import { isInside, specPathProblem, workspaceKey } from "./trigger_paths.js";
21	import { WorkspaceRateLimiter, type RateLimitDecision } from "./trigger_rate_limit.js";
22	import { planTriggerRun, type TriggerEvent } from "./trigger_run.js";
23	import type { TriggerRate, TriggerSpec } from "./trigger_spec.js";
24	import { decideTriggerTrust, readTriggerTrustStore, triggerMayRun, triggerTrustStorePath, workspaceMayHaveTriggers } from "./trigger_trust.js";
25	import { DEFAULT_MAX_TOTAL_DIRS, DirBudget, FileTriggerWatcher, type WatchFactory } from "./trigger_watch.js";
26	import { WebhookListener, type WebhookDelivery, type WebhookOutcome, type WebhookTarget } from "./trigger_webhook.js";
