28	
29	export const DEFAULT_TRIGGER_SCAN_MS = 5_000;
30	/** An inline or environment webhook secret shorter than this is not armed (the spec parser enforces it for inline ones). */
31	const MIN_ENV_SECRET = REDACTED;
