71	
72	export type FireResult = { started: true; jobId: string } | { started: false; reason: string; drop?: keyof TriggerDrops };
73	
74	const ISO = (ms: number) => new Date(ms).toISOString();
75	const oneLine = (text: string) => text.replace(/[\u0000-\u001f\u007f-\u009f]/g, " ").slice(0, 480);
76	
77	export class TriggerFirer {
78	  private readonly statePaths;
79	  private readonly armed = new Map<string, Armed>();
80	  private readonly webhooks = new Map<string, Armed>();
81	  private readonly runtime = new Map<string, TriggerRuntime>();
82	  private readonly budget: DirBudget;
83	  private readonly reported = new Map<string, string>();
84	  private readonly failuresSeen = new Set<string>();
85	  private readonly secretEnv = new Set<string>();
86	  private limiter: WorkspaceRateLimiter | undefined;
87	  private limiterProblem: string | undefined;
88	  private listener: WebhookListener | undefined;
89	  private listenerInfo: { host: string; port: number; pid: number; startedAt: string } | undefined;
90	  private starting: Promise<void> | undefined;
91	  private lastScan: number | undefined;
92	  private dirty = false;
93	  private closed = false;
94	  private trustProblem: string | undefined;
95	
96	  constructor(private readonly options: TriggerFirerOptions) {
97	    this.statePaths = triggerStatePaths(options.paths);
98	    this.budget = new DirBudget(options.watch?.maxTotalDirs ?? DEFAULT_MAX_TOTAL_DIRS);
99	  }
100	
101	  private now(): number {
102	    return this.options.now().getTime();
103	  }
104	
105	  /** The environment variables that hold webhook secrets; the runner removes them from a worker's environment. */
106	  secretEnvNames(): string[] {
107	    return [...this.secretEnv];
108	  }
109	
110	  /** Where the listener is, once open. */
111	  webhookAddress(): { host: string; port: number } | undefined {
112	    return this.listenerInfo ? { host: this.listenerInfo.host, port: this.listenerInfo.port } : undefined;
113	  }
114	
115	  /** Resolves once a listener start that is under way has finished (it has opened or failed). */
116	  async whenListening(): Promise<void> {
117	    await this.starting;
118	  }
119	
120	  /** What the firer holds for each trigger, as written to the state file. */
121	  snapshot(): TriggerRuntime[] {
122	    return [...this.runtime.values()].map((t) => ({ ...t, dropped: { ...t.dropped } }));
123	  }
124	
125	  // ---------------------------------------------------------------- the tick
126	
127	  /** One pass: at most every `scanMs` re-read what is approved and arm or disarm; every pass drain the watchers. Never throws. */
128	  tick(): void {
129	    if (this.closed) return;
130	    try {
131	      const nowMs = this.now();
132	      const interval = this.options.scanMs ?? DEFAULT_TRIGGER_SCAN_MS;
133	      if (this.lastScan === undefined || nowMs < this.lastScan || nowMs - this.lastScan >= interval) {
134	        this.lastScan = nowMs;
135	        this.scan();
136	      }
137	      this.drainWatchers(nowMs);
138	      if (this.dirty) this.persist();
139	    } catch (error) {
140	      this.options.log(`triggers: ${error instanceof Error ? error.message : String(error)}`);
141	    }
142	  }
143	
144	  private scan(): void {
145	    const entries = this.readEntries();
146	    if (entries.length === 0 && this.armed.size === 0 && this.runtime.size === 0) {
147	      // Nothing is approved and nothing was: leave no footprint, but still honour a pending release request.
148	      this.applyReleases();
149	      return;
150	    }
151	    this.ensureLimiter();
152	    this.applyReleases();
153	    const seen = new Set<string>();
154	    const scopes = new Map<string, typeof entries>();
155	    for (const entry of entries) scopes.set(entry.scope, [...(scopes.get(entry.scope) ?? []), entry]);
156	    for (const [scope, scoped] of scopes) {
157	      const outcomes = this.scanWorkspace(scope, scoped);
158	      for (const [id, outcome] of outcomes) {
159	        seen.add(triggerKey(scope, id));
160	        this.settle(scope, id, outcome);
161	      }
162	    }
163	    // An approval that is gone: revoked (or never seen) triggers stop at once.
164	    for (const key of [...this.armed.keys()]) if (!seen.has(key)) this.disarm(key);
165	    for (const [key, rt] of this.runtime) {
166	      if (seen.has(key)) continue;
167	      if (rt.seenApproved && rt.status !== "revoked") this.updateRuntime(rt, { status: "revoked", armed: false, note: "the approval was withdrawn" });
168	      else if (!rt.seenApproved && !this.armed.has(key)) this.runtime.delete(key);
169	    }
170	    while (this.runtime.size > MAX_TRACKED_TRIGGERS) this.runtime.delete(this.runtime.keys().next().value as string);
171	    this.reconcileListener();
172	    this.reapFailures();
173	  }
174	
175	  private readEntries() {
176	    const read = readTriggerTrustStore(this.options.trustStorePath ?? triggerTrustStorePath());
177	    if (read.problem !== this.trustProblem) {
178	      this.trustProblem = read.problem;
179	      if (read.problem) this.options.log(`triggers: the approvals cannot be used, so no trigger fires: ${read.problem}`);
180	    }
181	    return read.entries;
182	  }
183	
184	  /** The status and arming of every approved trigger of one workspace, from one read of its spec file. */
185	  private scanWorkspace(scope: string, entries: ReturnType<TriggerFirer["readEntries"]>): Map<string, { status: TriggerStatus; spec?: TriggerSpec; sha?: string; note?: string }> {
186	    const out = new Map<string, { status: TriggerStatus; spec?: TriggerSpec; sha?: string; note?: string }>();
187	    const all = (status: TriggerStatus, note: string) => { for (const e of entries) out.set(e.key, { status, note }); return out; };
188	    let real: string;
189	    try {
190	      real = fs.realpathSync(scope);
191	    } catch {
192	      return all("invalid", "the workspace does not exist");
193	    }
194	    if (real !== scope) return all("invalid", `the workspace now resolves to ${real}`);
195	    if (!workspaceMayHaveTriggers(real)) return all("untrusted", "the workspace is not in your trusted-workspaces store");
196	    const parsed = parseTriggerFile(triggerFilePath(real));
197	    if (parsed.problem) return all("invalid", parsed.problem);
198	    for (const entry of entries) {
199	      const spec = parsed.specs.find((s) => s.id === entry.key);
200	      if (!spec) { out.set(entry.key, { status: "invalid", note: "the spec is no longer in .nexus/triggers.json" }); continue; }
201	      const sha = specSha256(spec);
202	      if (sha !== entry.sha256) { out.set(entry.key, { status: "changed", spec, sha, note: "the spec changed since it was approved" }); continue; }
203	      const problem = specPathProblem(real, spec);
204	      out.set(entry.key, problem ? { status: "invalid", spec, sha, note: problem } : { status: "approved", spec, sha });
205	    }
206	    return out;
207	  }
208	
209	  private settle(scope: string, id: string, outcome: { status: TriggerStatus; spec?: TriggerSpec; sha?: string; note?: string }): void {
210	    const key = triggerKey(scope, id);
211	    const kind = outcome.spec?.event.kind ?? this.runtime.get(key)?.kind ?? "file-change";
212	    const rt = this.runtimeFor(scope, id, kind);
213	    if (outcome.status !== "approved" || !outcome.spec || !outcome.sha) {
214	      this.disarm(key);
215	      this.updateRuntime(rt, { status: outcome.status, armed: false, note: outcome.note, kind });
216	      return;
217	    }
218	    const armed = this.arm(scope, outcome.spec, outcome.sha);
219	    this.updateRuntime(rt, { status: "approved", seenApproved: true, armed: armed.armed, note: armed.note, kind, webhookPath: outcome.spec.event.kind === "webhook" ? `/hook/${workspaceKey(scope)}/${id}` : undefined, watchedDirs: this.armed.get(key)?.watcher?.dirs });
220	  }
221	
222	  private arm(scope: string, spec: TriggerSpec, sha: string): { armed: boolean; note?: string } {
223	    const key = triggerKey(scope, spec.id);
224	    const existing = this.armed.get(key);
225	    if (existing && existing.sha !== sha) this.disarm(key);
226	    if (spec.event.kind === "file-change") {
227	      if (this.options.fileWatch === false) return { armed: false, note: "file watching is off for this runner" };
228	      let entry = this.armed.get(key);
229	      if (!entry) {
230	        const watcher = new FileTriggerWatcher({ workspace: scope, globs: spec.event.paths ?? [], budget: this.budget, maxDirs: this.options.watch?.maxDirs, maxPending: this.options.watch?.maxPending, debounceMs: this.options.watch?.debounceMs, watch: this.options.watch?.watch, now: () => this.now() });
231	        entry = { workspace: scope, id: spec.id, kind: "file-change", sha, spec, watcher };
232	        this.armed.set(key, entry);
233	      }
234	      entry.watcher!.reconcile();
235	      const notes = entry.watcher!.errors;
236	      if (entry.watcher!.dirs === 0 && notes.length === 0) return { armed: true, note: "no directory to watch yet (its first directory does not exist)" };
237	      return { armed: entry.watcher!.dirs > 0, note: notes.length ? oneLine(notes.join("; ")) : undefined };
238	    }
239	    // webhook
240	    if (!this.options.webhook) return { armed: false, note: "the webhook listener is off: start the runner with --webhook-port" };
241	    const name = spec.event.secretEnv;
242	    if (name) this.secretEnv.add(name);
243	    const secret = spec.event.secret ?? (name ? (this.options.env ?? process.env)[name] : undefined);
244	    if (!secret || secret.length < MIN_ENV_SECRET) return { armed: false, note: name ? `the secret environment variable ${name} is not set, or is shorter than ${MIN_ENV_SECRET} characters` : "the secret is shorter than 16 characters" };
245	    const entry: Armed = existing && existing.sha === sha ? existing : { workspace: scope, id: spec.id, kind: "webhook", sha, spec, target: { secret: Buffer.from(secret, "utf8"), allowedOrigins: spec.event.allowedOrigins ?? [] } };
246	    this.armed.set(key, entry);
247	    this.webhooks.set(`${workspaceKey(scope)}/${spec.id}`, entry);
248	    return { armed: true };
249	  }
250	
251	  private disarm(key: string): void {
252	    const entry = this.armed.get(key);
253	    if (!entry) return;
254	    entry.watcher?.close();
255	    this.armed.delete(key);
256	    this.webhooks.delete(`${workspaceKey(entry.workspace)}/${entry.id}`);
257	  }
258	
259	  private runtimeFor(workspace: string, id: string, kind: TriggerRuntime["kind"]): TriggerRuntime {
260	    const key = triggerKey(workspace, id);
261	    let rt = this.runtime.get(key);
262	    if (!rt) {
263	      rt = { workspace, id, kind, status: "not_approved", armed: false, fired: 0, refused: 0, dropped: { ...NO_DROPS } };
264	      this.runtime.set(key, rt);
265	      this.dirty = true;
266	    }
267	    return rt;
268	  }
269	
270	  private updateRuntime(rt: TriggerRuntime, change: Partial<TriggerRuntime> & { note?: string | undefined }): void {
271	    const before = JSON.stringify(rt);
272	    Object.assign(rt, change);
273	    for (const field of ["note", "webhookPath", "watchedDirs", "seenApproved"] as const) if (change[field] === undefined && field in change) delete rt[field];
274	    if (JSON.stringify(rt) !== before) this.dirty = true;
275	  }
276	
277	  // ---------------------------------------------------------------- the limiter
278	
279	  private ensureLimiter(): WorkspaceRateLimiter {
280	    if (this.limiter) return this.limiter;
281	    const limiter = new WorkspaceRateLimiter(this.options.workspaceLimits);
282	    this.limiter = limiter;
283	    let doc: ReturnType<typeof readTriggerState>;
284	    try {
285	      doc = readTriggerState(this.statePaths);
286	    } catch (error) {
287	      limiter.restore(null);
288	      this.limiterProblem = oneLine(`the stored trigger state cannot be used (${error instanceof Error ? error.message : String(error)}); every firing is denied until \`nexus triggers release --limiter\``);
289	      this.options.log(`triggers: ${this.limiterProblem}`);
290	      this.dirty = true;
291	      return limiter;
292	    }
293	    if (!doc) return limiter;
294	    for (const t of doc.triggers) this.runtime.set(triggerKey(t.workspace, t.id), t);
295	    if (doc.limiterProblem) {
296	      limiter.restore(null);
297	      this.limiterProblem = doc.limiterProblem;
298	    } else if (doc.limiter !== undefined && !limiter.restore(doc.limiter)) {
299	      const snap = limiter.snapshot();
300	      if (snap.perTrigger.length === 0 && snap.quarantines.length === 0) {
301	        this.limiterProblem = "the stored limiter state was invalid; every firing is denied until `nexus triggers release --limiter`";
302	        this.dirty = true;
303	      }
304	      this.options.log(`triggers: ${this.limiterProblem ?? "a stored limiter entry was invalid; that trigger stays quarantined until released"}`);
305	    }
306	    return limiter;
307	  }
308	
309	  private admit(a: Armed, nowMs: number): RateLimitDecision {
310	    const limiter = this.ensureLimiter();
311	    const decision = limiter.checkAndRecord(a.workspace, a.id, a.spec.rate, new Date(nowMs));
312	    this.dirty = true;
313	    return decision;
314	  }
315	
316	  private applyReleases(): void {
317	    let taken: ReturnType<typeof takeReleases>;
318	    try {
319	      taken = takeReleases(this.statePaths);
320	    } catch {
321	      return;
322	    }
323	    for (const bad of taken.invalid) this.options.log(`triggers: a release request was refused: ${bad}`);
324	    if (taken.requests.length === 0) return;
325	    const limiter = this.ensureLimiter();
326	    for (const request of taken.requests) {
327	      if (request.id) {
328	        limiter.releaseQuarantine(request.workspace, request.id);
329	        const rt = this.runtime.get(triggerKey(request.workspace, request.id));
330	        if (rt) this.updateRuntime(rt, { note: undefined });
331	        this.options.log(`triggers: ${request.id} released from quarantine by the operator`);
332	      }
333	      if (request.limiter) {
334	        limiter.clearLock();
335	        this.limiterProblem = undefined;
336	        this.options.log("triggers: the limiter was unlocked by the operator");
337	      }
338	    }
339	    this.dirty = true;
340	  }
341	
342	  // ---------------------------------------------------------------- events
343	
344	  private drainWatchers(nowMs: number): void {
345	    for (const a of this.armed.values()) {
346	      const watcher = a.watcher;
347	      if (!watcher) continue;
348	      watcher.reconcile();
349	      const rt = this.runtime.get(triggerKey(a.workspace, a.id));
350	      if (rt) this.updateRuntime(rt, { watchedDirs: watcher.dirs, note: watcher.errors.length ? oneLine(watcher.errors.join("; ")) : rt.note });
351	      const batch = watcher.drain(nowMs);
352	      if (!batch) continue;
353	      if (rt && (batch.droppedPending || batch.droppedEscape)) {
354	        rt.dropped.pending += batch.droppedPending;
355	        rt.dropped.escape += batch.droppedEscape;
356	        this.dirty = true;
357	      }
358	      if (batch.paths.length === 0) continue;
359	      const id = `fc-${createHash("sha256").update(`${a.id}\0${Math.floor(nowMs / 1000)}\0${batch.paths.join("\0")}`).digest("hex").slice(0, 24)}`;
360	      this.fire(a, { id, kind: "file-change", paths: batch.paths, morePaths: batch.droppedPending });
361	    }
362	  }
363	
364	  /** The listener's callback for an authenticated delivery: the limiter runs here, after authentication. */
365	  private onDelivery(delivery: WebhookDelivery, nowMs: number): WebhookOutcome {
366	    const a = this.webhooks.get(`${delivery.workspaceKey}/${delivery.id}`);
367	    if (!a) return { accepted: false, reason: "refused" };
368	    const decision = this.admit(a, nowMs);
369	    if (!decision.admitted) {
370	      const quarantined = decision.reason === "quarantined";
371	      this.countDrop(a, quarantined ? "quarantined" : "rateLimited", decision.reason ?? "refused");
372	      return { accepted: false, reason: quarantined ? "quarantined" : "rate-limited" };
373	    }
374	    const id = `wh-${createHash("sha256").update(delivery.deliveryId).digest("hex").slice(0, 24)}`;
375	    const result = this.fire(a, { id, kind: "webhook", body: delivery.body.subarray(0, 4096), bodyBytes: delivery.body.length }, { admitted: true });
376	    return result.started ? { accepted: true } : { accepted: false, reason: result.drop === "overlap" ? "busy" : "refused" };
377	  }
378	
379	  /**
380	   * One event of an armed trigger. The order is the design: a repeated id or a still-running previous job is dropped
381	   * first (they cost nothing), then the approval is re-read and checked, then the limiter (unless a webhook already
382	   * passed it after authenticating), and only then is a job submitted from the spec that was just read.
383	   */
384	  fire(a: Armed, event: TriggerEvent, opts: { admitted?: boolean } = {}): FireResult {
385	    const nowMs = this.now();
386	    const jobs = this.jobsNow();
387	    const own = jobs.filter((job) => job.origin.kind === "trigger" && job.origin.triggerId === a.id && job.workspace === a.workspace);
388	    if (own.some((job) => job.origin.kind === "trigger" && job.origin.eventId === event.id)) return this.countDrop(a, "duplicate", `event ${event.id} already started a job`);
389	    if (own.some((job) => !isTerminal(job.state))) return this.countDrop(a, "overlap", "the previous job of this trigger is still running");
390	
391	    const verified = this.verify(a);
392	    if (!verified.ok) return this.refuse(a, verified.reason);
393	    const { spec, sha } = verified;
394	
395	    if (!opts.admitted) {
396	      const decision = this.admit(a, nowMs);
397	      if (!decision.admitted) return this.countDrop(a, decision.reason === "quarantined" ? "quarantined" : "rateLimited", decision.reason === "quarantined" ? `quarantined: ${decision.quarantined?.reason ?? "too many failures"}` : (decision.reason ?? "rate limit"));
398	    }
399	    let plan: ReturnType<typeof planTriggerRun>;
400	    try {
401	      plan = planTriggerRun({ workspace: a.workspace, spec, event, approvedSha256: sha });
402	      this.options.submit(plan.job, plan.spec);
403	    } catch (error) {
404	      if (!(error instanceof RunnerStoreError)) throw error;
405	      return this.refuse(a, `the job could not be submitted: ${error.message}`);
406	    }
407	    const rt = this.runtimeFor(a.workspace, a.id, a.kind);
408	    rt.fired++;
409	    rt.lastFire = { at: ISO(nowMs), jobId: plan.job.id, eventId: event.id };
410	    this.dirty = true;
411	    this.reported.delete(triggerKey(a.workspace, a.id));
412	    this.options.log(`trigger ${a.id}: ${event.kind} event ${event.id} started job ${plan.job.id}`);
413	    return { started: true, jobId: plan.job.id };
414	  }
415	
416	  /** The approval as it stands right now, from fresh reads. Fires only from the spec these reads produce. */
417	  private verify(a: Armed): { ok: true; spec: TriggerSpec; sha: string } | { ok: false; reason: string } {
418	    let real: string;
419	    try {
420	      real = fs.realpathSync(a.workspace);
421	    } catch {
422	      return { ok: false, reason: "the workspace does not exist" };
423	    }
424	    if (real !== a.workspace) return { ok: false, reason: `the workspace now resolves to ${real}` };
425	    const store = readTriggerTrustStore(this.options.trustStorePath ?? triggerTrustStorePath());
426	    if (store.problem) return { ok: false, reason: `the approvals cannot be used: ${store.problem}` };
427	    const parsed = parseTriggerFile(triggerFilePath(real));
428	    if (parsed.problem) return { ok: false, reason: parsed.problem };
429	    const spec = parsed.specs.find((s) => s.id === a.id);
430	    const sha = spec ? specSha256(spec) : undefined;
431	    const decision = decideTriggerTrust(store.entries, real, spec, sha);
432	    if (!triggerMayRun(decision) || !spec || !sha) {
433	      const rt = this.runtimeFor(a.workspace, a.id, a.kind);
434	      const status: TriggerStatus = !decision.workspaceTrusted ? "untrusted" : decision.status === "MISMATCH" ? "changed" : decision.status === "NEW" ? (rt.seenApproved ? "revoked" : "not_approved") : "invalid";
435	      this.updateRuntime(rt, { status, armed: false });
436	      return { ok: false, reason: decision.reason };
437	    }
438	    if (sha !== a.sha) return { ok: false, reason: "the spec changed after the event was matched; it fires only from the spec its event was matched under" };
439	    const problem = specPathProblem(real, spec);
440	    if (problem) return { ok: false, reason: problem };
441	    if (!isInside(real, real)) return { ok: false, reason: "the workspace is not a directory" };
442	    return { ok: true, spec, sha };
443	  }
444	
445	  private jobsNow(): JobRecord[] {
446	    return (this.options.jobs ?? (() => listJobs(this.options.paths).jobs))();
447	  }
448	
449	  private refuse(a: Armed, reason: string): FireResult {
450	    const key = triggerKey(a.workspace, a.id);
451	    const rt = this.runtimeFor(a.workspace, a.id, a.kind);
452	    const text = oneLine(reason);
453	    rt.refused++;
454	    rt.lastRefusal = { at: ISO(this.now()), reason: text };
455	    this.dirty = true;
456	    if (this.reported.get(key) !== text) {
457	      this.reported.set(key, text);
458	      this.options.log(`trigger ${a.id}: not fired: ${text}`);
459	    }
460	    return { started: false, reason: text };
461	  }
462	
463	  private countDrop(a: Armed, drop: keyof TriggerDrops, reason: string): FireResult {
464	    const rt = this.runtimeFor(a.workspace, a.id, a.kind);
465	    rt.dropped[drop]++;
466	    this.refuse(a, reason);
467	    return { started: false, reason: oneLine(reason), drop };
468	  }
469	
470	  /** A trigger's job that failed or timed out counts toward that trigger's quarantine, once. */
471	  private reapFailures(): void {
472	    const limiter = this.limiter;
473	    if (!limiter || this.armed.size === 0) return;
474	    const jobs = this.jobsNow();
475	    const live = new Set(jobs.map((job) => job.id));
476	    for (const id of this.failuresSeen) if (!live.has(id)) this.failuresSeen.delete(id);
477	    for (const job of jobs) {
478	      if (job.origin.kind !== "trigger" || (job.state !== "FAILED" && job.state !== "TIMED_OUT") || this.failuresSeen.has(job.id)) continue;
479	      this.failuresSeen.add(job.id);
480	      const a = this.armed.get(triggerKey(job.workspace, job.origin.triggerId));
481	      if (!a) continue;
482	      limiter.recordFailure(a.workspace, a.id, a.spec.rate, this.options.now(), `job ${job.id} ${job.state.toLowerCase()}`);
483	      this.dirty = true;
484	    }
485	  }
486	
487	  // ---------------------------------------------------------------- the listener
488	
489	  private reconcileListener(): void {
490	    const config = this.options.webhook;
491	    if (!config) return;
492	    if (this.webhooks.size === 0) {
493	      if (this.listener) void this.closeListener();
494	      return;
495	    }
496	    if (this.listener || this.starting || this.closed) return;
497	    const listener = new WebhookListener({
498	      host: config.host ?? "127.0.0.1",
499	      port: config.port,
500	      allowNonLoopback: config.allowNonLoopback,
501	      hasAuthentication: () => this.webhooks.size > 0,
502	      lookup: (wskey, id) => this.webhooks.get(`${wskey}/${id}`)?.target,
503	      onDelivery: (delivery, nowMs) => this.onDelivery(delivery, nowMs),
504	      maxBodyBytes: config.maxBodyBytes,
505	      requestTimeoutMs: config.requestTimeoutMs,
506	      maxConnections: config.maxConnections,
507	      now: () => this.now(),
508	    });
509	    this.starting = listener.start().then((address) => {
510	      if (this.closed) { void listener.close(); return; }
511	      this.listener = listener;
512	      this.listenerInfo = { host: address.host, port: address.port, pid: process.pid, startedAt: ISO(this.now()) };
513	      this.dirty = true;
514	      this.options.log(`triggers: webhook listener open on ${address.host}:${address.port}`);
515	    }, (error) => {
516	      const why = oneLine(error instanceof Error ? error.message : String(error));
517	      this.options.log(`triggers: the webhook listener did not start: ${why}`);
518	      for (const a of this.webhooks.values()) {
519	        const rt = this.runtime.get(triggerKey(a.workspace, a.id));
520	        if (rt) this.updateRuntime(rt, { armed: false, note: `the webhook listener did not start: ${why}` });
521	      }
522	    }).finally(() => { this.starting = undefined; });
523	  }
524	
525	  private async closeListener(): Promise<void> {
526	    const listener = this.listener;
527	    this.listener = undefined;
528	    this.listenerInfo = undefined;
529	    this.dirty = true;
530	    await listener?.close();
531	  }
532	
533	  // ---------------------------------------------------------------- state
534	
535	  private persist(): void {
536	    this.dirty = false;
537	    if (!this.limiter && this.runtime.size === 0) return;
538	    try {
539	      writeTriggerState(this.statePaths, {
540	        format: "nexus-trigger-state",
541	        version: 1,
542	        updatedAt: this.options.now().toISOString(),
543	        ...(this.limiter ? { limiter: this.limiter.snapshot() } : {}),
544	        ...(this.limiterProblem ? { limiterProblem: this.limiterProblem } : {}),
545	        ...(this.listenerInfo ? { listener: this.listenerInfo } : {}),
546	        triggers: [...this.runtime.values()].slice(0, MAX_TRACKED_TRIGGERS),
547	      });
548	    } catch (error) {
549	      this.options.log(`triggers: the state could not be written: ${error instanceof Error ? error.message : String(error)}`);
550	    }
551	  }
552	
553	  /** Stops every watcher and the listener (waiting for the socket to close) and writes the state once more. */
554	  async close(): Promise<void> {
555	    this.closeNow();
556	    await this.starting?.catch(() => undefined);
557	    await this.closeListener();
558	    if (this.dirty) this.persist();
559	  }
560	
561	  /** The synchronous part of `close`: watchers closed, nothing more is armed. For a runner that is being abandoned. */
562	  closeNow(): void {
563	    this.closed = true;
564	    for (const key of [...this.armed.keys()]) this.disarm(key);
565	    void this.listener?.close();
566	  }
567	}
