1	/**
2	 * BG-3: the file-change watcher of one trigger. Bounded in every direction, and quiet by design:
3	 *
4	 *  - at most `maxDirs` directories are watched (the walk starts at the directory each glob names and never follows a
5	 *    symbolic link), and the runner shares one `DirBudget` across all its watchers;
6	 *  - at most `maxPending` distinct changed paths wait for the next window; later ones are only counted (`droppedPending`);
7	 *  - events are coalesced: the first event opens a window of `debounceMs` and everything inside it is one batch.
8	 *    The watcher holds no timer: the runner's tick calls `drain`, so a closed watcher leaves nothing behind;
9	 *  - `.git/`, `.nexus/` and the trigger files never count (trigger_paths.ts), and a path whose real path leaves the
10	 *    workspace is dropped and counted (`droppedEscape`);
11	 *  - a watcher error (inotify limits, a vanished directory) is kept in `errors` and shown, never swallowed.
12	 *
13	 * What an event carries is the workspace-relative path only, and the watcher decides nothing about firing.
14	 */
15	import * as fs from "node:fs";
16	import * as path from "node:path";
17	import { globToRegExp, globWatchRoot, isExcludedEventPath, resolveInside, EXCLUDED_SEGMENTS } from "./trigger_paths.js";
18	
19	export const DEFAULT_MAX_DIRS = 256;
20	export const DEFAULT_MAX_TOTAL_DIRS = 1024;
21	export const DEFAULT_MAX_PENDING = 1000;
22	export const DEFAULT_DEBOUNCE_MS = 2_000;
23	const MAX_ERRORS = 5;
24	
25	export type WatchFactory = (dir: string, listener: (event: string, name: string | Buffer | null) => void) => fs.FSWatcher;
26	
27	/** Directories the runner may watch in all, across triggers. */
28	export class DirBudget {
29	  private used = 0;
30	  constructor(readonly max: number = DEFAULT_MAX_TOTAL_DIRS) {}
31	  take(): boolean {
32	    if (this.used >= this.max) return false;
33	    this.used++;
34	    return true;
35	  }
36	  give(count: number): void {
37	    this.used = Math.max(0, this.used - count);
38	  }
39	}
40	
41	export interface WatchBatch {
42	  /** Distinct changed paths, workspace-relative with `/`, sorted. */
43	  paths: string[];
44	  /** Paths beyond the pending bound that were counted but not kept. */
45	  droppedPending: number;
46	  /** Paths that resolved outside the workspace in this window. */
47	  droppedEscape: number;
48	}
49	
50	export interface FileWatcherOptions {
51	  /** The workspace's real path. */
52	  workspace: string;
53	  globs: readonly string[];
54	  budget: DirBudget;
55	  maxDirs?: number;
56	  maxPending?: number;
57	  debounceMs?: number;
58	  watch?: WatchFactory;
59	  /** The clock `drain` is called with (epoch ms). */
60	  now?: () => number;
61	}
62	
63	const defaultWatch: WatchFactory = (dir, listener) => fs.watch(dir, { persistent: false }, listener);
64	
65	export class FileTriggerWatcher {
66	  private readonly matchers: RegExp[];
67	  private readonly watchers = new Map<string, fs.FSWatcher>();
68	  private readonly pending = new Set<string>();
69	  private firstAt: number | undefined;
70	  private droppedPending = 0;
71	  private droppedEscape = 0;
72	  private rescan = true;
73	  private closed = false;
74	  readonly errors: string[] = [];
75	  /** The walk reached `maxDirs` or the shared budget: some directories are not watched. */
76	  truncated = false;
77	
78	  constructor(private readonly options: FileWatcherOptions) {
79	    this.matchers = options.globs.map(globToRegExp);
80	  }
81	
82	  get dirs(): number {
83	    return this.watchers.size;
84	  }
85	
86	  private note(message: string): void {
87	    if (this.errors.length < MAX_ERRORS && !this.errors.includes(message)) this.errors.push(message);
88	  }
89	
90	  /** Watches every directory the globs need that is not watched yet. Called by the runner's tick, cheap when nothing changed. */
91	  reconcile(): void {
92	    if (this.closed || !this.rescan) return;
93	    this.rescan = false;
94	    const maxDirs = this.options.maxDirs ?? DEFAULT_MAX_DIRS;
95	    const roots = new Map<string, number>();
96	    for (const glob of this.options.globs) {
97	      const { prefix, depth } = globWatchRoot(glob);
98	      const root = path.join(this.options.workspace, ...prefix);
99	      roots.set(root, Math.max(roots.get(root) ?? 0, depth));
100	    }
101	    const walk: Array<[string, number]> = [...roots.entries()];
102	    for (let i = 0; i < walk.length; i++) {
103	      const [dir, depth] = walk[i]!;
104	      if (!this.watchers.has(dir)) {
105	        if (this.watchers.size >= maxDirs || !this.options.budget.take()) {
106	          this.truncated = true;
107	          this.note(`watching stopped at ${this.watchers.size} directories (limit ${maxDirs}, shared limit ${this.options.budget.max}); changes in the others are not seen`);
108	          continue;
109	        }
110	        if (!this.attach(dir)) {
111	          this.options.budget.give(1);
112	          continue;
113	        }
114	      }
115	      if (depth <= 0) continue;
116	      let entries: fs.Dirent[];
117	      try {
118	        entries = fs.readdirSync(dir, { withFileTypes: true });
119	      } catch (error) {
120	        this.note(`cannot read ${path.relative(this.options.workspace, dir) || "."}: ${(error as NodeJS.ErrnoException).code ?? "error"}`);
121	        continue;
122	      }
123	      for (const entry of entries) {
124	        // A symbolic link is never followed: what it points at is not the workspace's own tree.
125	        if (!entry.isDirectory() || entry.isSymbolicLink() || EXCLUDED_SEGMENTS.includes(entry.name)) continue;
126	        walk.push([path.join(dir, entry.name), depth - 1]);
127	      }
128	    }
129	  }
130	
131	  private attach(dir: string): boolean {
132	    const watch = this.options.watch ?? defaultWatch;
133	    try {
134	      const watcher = watch(dir, (event, name) => this.onEvent(dir, event, name));
135	      watcher.on("error", (error: NodeJS.ErrnoException) => {
136	        this.note(`watching ${path.relative(this.options.workspace, dir) || "."} failed: ${error.code ?? error.message}`);
137	        watcher.close();
138	        this.watchers.delete(dir);
139	        this.options.budget.give(1);
140	      });
141	      this.watchers.set(dir, watcher);
142	      return true;
143	    } catch (error) {
