1	/**
2	 * BG-3: what the trigger firer remembers, `<runner root>/nexus-triggers/` (0700, every file 0600).
3	 *
4	 * `state.json` holds the rate limiter's snapshot (validated by `WorkspaceRateLimiter.restore` on load) and, per
5	 * trigger, what the operator needs to see: whether it is armed, when it last fired, why it last refused, and how many
6	 * events were dropped and why. The runner is its only writer. `nexus triggers release` does not write it: it leaves a
7	 * request file here that the runner applies, so two processes never write the limiter at once.
8	 *
9	 * The directory name starts with `nexus-triggers`, which Nexus's own file tools refuse (security.ts), so the agent a
10	 * triggered job runs cannot reset a limit or a quarantine. That is not a defence against your own account.
11	 */
12	import { createHash } from "node:crypto";
13	import * as fs from "node:fs";
14	import * as path from "node:path";
15	import { ensurePrivateDir } from "./durable_file.js";
16	import { assertPrivateDir, integer, oneOf, readPrivateJson, RunnerStoreError, strictObject, text, timestamp, writePrivateJson, type RunnerPaths } from "./runner_store.js";
17	
18	export const TRIGGER_STATE_VERSION = 1;
19	export const MAX_TRACKED_TRIGGERS = 256;
20	const STATE_LIMIT = 4 * 1024 * 1024;
21	const RELEASE_LIMIT = 4 * 1024;
22	const MAX_RELEASES_PER_PASS = 64;
23	
24	export const TRIGGER_STATUSES = ["approved", "changed", "not_approved", "revoked", "untrusted", "invalid"] as const;
25	export type TriggerStatus = (typeof TRIGGER_STATUSES)[number];
26	
27	/** Events that did not start a job, by why. Never replayed. */
28	export interface TriggerDrops {
29	  rateLimited: number;
30	  quarantined: number;
31	  /** The trigger's previous job was still running (the loop guard for the trigger's own work). */
32	  overlap: number;
33	  /** More events than the watcher's pending bound held in one window. */
34	  pending: number;
35	  /** An event path that resolved outside the workspace. */
36	  escape: number;
37	  /** The same event id again. */
38	  duplicate: number;
39	}
40	export const NO_DROPS: TriggerDrops = { rateLimited: 0, quarantined: 0, overlap: 0, pending: 0, escape: 0, duplicate: 0 };
41	
42	export interface TriggerRuntime {
43	  workspace: string;
44	  id: string;
45	  kind: "file-change" | "webhook";
46	  status: TriggerStatus;
47	  /** Whether the firer is watching or listening for it now. */
48	  armed: boolean;
49	  /** Why it is not armed, or a limit it hit (a watcher error, a missing secret). */
50	  note?: string;
51	  /** Seen approved at some scan, so a later missing approval reads as revoked. */
52	  seenApproved?: boolean;
53	  fired: number;
54	  refused: number;
55	  lastFire?: { at: string; jobId: string; eventId: string };
56	  lastRefusal?: { at: string; reason: string };
57	  dropped: TriggerDrops;
58	  /** Webhook: the URL path that delivers to it. */
59	  webhookPath?: string;
60	  /** File watch: directories watched. */
61	  watchedDirs?: number;
62	}
63	
64	export interface TriggerStateDoc {
65	  format: "nexus-trigger-state";
66	  version: typeof TRIGGER_STATE_VERSION;
67	  updatedAt: string;
68	  /** `WorkspaceRateLimiter.snapshot()`; restored with `restore()`, which refuses anything invalid. */
69	  limiter?: unknown;
70	  /** Set when the limiter's stored state was refused on load: every firing is denied until `nexus triggers release --limiter`. */
71	  limiterProblem?: string;
72	  /** The webhook listener, while it is open. */
73	  listener?: { host: string; port: number; pid: number; startedAt: string };
74	  triggers: TriggerRuntime[];
75	}
76	
77	export interface TriggerStatePaths {
78	  dir: string;
79	  state: string;
80	  release: (workspace: string, id: string | null) => string;
81	}
82	
83	export function triggerStatePaths(runner: Pick<RunnerPaths, "root">): TriggerStatePaths {
84	  const dir = path.join(runner.root, "nexus-triggers");
85	  return {
86	    dir,
