import { test } from "node:test";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { listJobs } from "../src/core/runner_store.js";
import { readTriggerState, triggerStatePaths } from "../src/core/trigger_state.js";
import { makeRepo } from "./helpers/fixtures.js";
import { runnerWorld, stalledGateway, until } from "./helpers/runner_fixture.js";
import { trustRepo } from "./helpers/schedule_fixture.js";
import { approveInRepo, fileSpec, hookPath, post, signed, webhookSpec } from "./helpers/trigger_fixture.js";

const SECRET = "ZZsecretZZ0123456789abcdefXYZ";
const out = (...a: unknown[]) => console.log("PROBE", ...a);
const jobsOf = (w: any) => listJobs(w.paths).jobs.filter((j: any) => j.origin.kind === "trigger");
const st = (w: any) => { try { return readTriggerState(triggerStatePaths(w.paths)); } catch (e) { return undefined; } };
const inotify = (pid: number) => fs.readdirSync(`/proc/${pid}/fd`).filter((fd) => { try { return fs.readlinkSync(`/proc/${pid}/fd/${fd}`).includes("inotify"); } catch { return false; } }).length;
const socks = (pid: number) => { const held = new Set(fs.readdirSync(`/proc/${pid}/fd`).map((fd) => { try { return /^socket:\[(\d+)\]$/.exec(fs.readlinkSync(`/proc/${pid}/fd/${fd}`))?.[1]; } catch { return undefined; } }).filter(Boolean)); return fs.readFileSync(`/proc/${pid}/net/tcp`, "utf8").split("\n").slice(1).map((l) => l.trim().split(/\s+/)).filter((c) => c[3] === "0A" && held.has(c[9]!)).map((c) => c[1]); };

test("probe A: no-trigger runner, --no-triggers, remote bind, lock", { timeout: 280_000 }, async () => {
  const w = runnerWorld(); const repo = fs.realpathSync(makeRepo({ "src/a.ts": "a\n" })); const gw = await stalledGateway();
  const env = { LOCAL_LLM_ENDPOINT: gw.url, LOCAL_LLM_MODEL: "m", NEXUS_PROBE_SECRET: SECRET };
  try {
    await trustRepo(w, repo);
    approveInRepo(w, repo, [webhookSpec("hook", "NEXUS_PROBE_SECRET"), fileSpec("fc", ["src/**/*.ts"])]);
    // (1) no-triggers with approved triggers
    const r0 = await w.startRunner(["--no-triggers"], env); await new Promise((r) => setTimeout(r, 7000));
    out("no-triggers: inotify", inotify(r0.proc.pid!), "socks", socks(r0.proc.pid!), "statedir", fs.existsSync(triggerStatePaths(w.paths).dir));
    // (2) second runner while first holds lock
    const r1 = w.spawn(["runner", "serve", "--webhook-port", "0"], env); const ex = await Promise.race([r1.exited, new Promise((r) => setTimeout(() => r("still running"), 8000))]);
    out("second runner:", JSON.stringify(ex), r1.stderr().slice(0, 200));
    r0.proc.kill("SIGTERM"); await r0.exited;
    // (3) remote bind refused without flag
    const r2 = await w.startRunner(["--webhook-port", "0", "--webhook-host", "0.0.0.0"], env);
    await until(() => st(w)?.triggers.find((t) => t.id === "hook")?.note || st(w)?.listener, 60_000, () => "note");
    out("0.0.0.0 no flag: listener", JSON.stringify(st(w)?.listener), "note", st(w)?.triggers.find((t) => t.id === "hook")?.note, "socks", socks(r2.proc.pid!), "inotify", inotify(r2.proc.pid!));
    out("stderr", r2.stderr().slice(0, 300));
    r2.proc.kill("SIGTERM"); await r2.exited;
    // (4) remote bind allowed
    const r3 = await w.startRunner(["--webhook-port", "0", "--webhook-host", "0.0.0.0", "--webhook-allow-remote"], env);
    await until(() => st(w)?.listener, 60_000, () => "listener");
    out("0.0.0.0 with flag: listener", JSON.stringify(st(w)?.listener), "socks", socks(r3.proc.pid!));
    // secrets: fire one webhook with the real runner, then grep everything
    const lp = st(w)!.listener!.port; const body = '{"hi":1}';
    out("post", JSON.stringify(await post(lp, hookPath(repo, "hook"), body, signed(SECRET, body, { delivery: "probe-del-0001" }))));
    const job = await until(() => jobsOf(w)[0], 60_000, () => "job");
    await until(() => w.job(job.id)?.attempts[0], 120_000, () => "attempt");
    const environ = fs.readFileSync(`/proc/${w.job(job.id)!.attempts[0]!.pid}/environ`, "latin1");
    out("worker environ has var:", environ.includes("NEXUS_PROBE_SECRET"), "secret:", environ.includes(SECRET));
    // grep runner tree for secret
    const hits: string[] = []; const walk = (d: string) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else { try { if (fs.readFileSync(p, "latin1").includes(SECRET)) hits.push(p); } catch {} } } };
    walk(w.root); out("files containing secret under world:", JSON.stringify(hits), "runner stderr has secret:", r3.stderr().includes(SECRET));
    out("job dir size", fs.readdirSync(path.join(w.paths.root, "jobs")).length, "worktree dirs", fs.existsSync(path.join(repo, ".nexus", "worktrees")) ? fs.readdirSync(path.join(repo, ".nexus", "worktrees")) : "none");
    const stat = (await w.run(["triggers", "status", "hook", "-w", repo])).stdout; out("status:\n" + stat);
    const ft = await w.run(["triggers", "fire-test", "hook", "-w", repo, "--body", "x"]); out("fire-test code", ft.code, "jobs now", jobsOf(w).length, "listeners same", socks(r3.proc.pid!).length);
    const ap = await w.run(["triggers", "approve", "-w", repo]); out("approve non-tty code", ap.code, ap.stderr.slice(0, 200));
    const rl = await w.run(["triggers", "release", "hook", "--limiter", "-w", repo]); out("release non-tty code", rl.code, rl.stderr.slice(0, 160));
    // corrupt state
    r3.proc.kill("SIGTERM"); await r3.exited;
    fs.writeFileSync(triggerStatePaths(w.paths).state, "{not json", { mode: 0o600 });
    const cs = await w.run(["triggers", "status", "hook", "-w", repo]); out("corrupt state status code", cs.code, cs.stdout.split("\n").filter((l) => /runner|may run/.test(l)).join(" | "));
  } finally { await w.cleanup(); await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
});
EOF
